package com.nexvio.app

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.compose.animation.*
import androidx.compose.foundation.background
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp

private val Ink = Color(0xFF101114)
private val Panel = Color(0xFF1B1D22)
private val Lime = Color(0xFFB7F36B)
private val Muted = Color(0xFF9A9DA6)

class MainActivity : ComponentActivity() { override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState); setContent { NexvioApp() } } }

@Composable fun NexvioApp() { var current by remember { mutableStateOf("Home") }; var detail by remember { mutableStateOf<String?>(null) }; MaterialTheme(colorScheme = darkColorScheme(primary=Lime, background=Ink, surface=Panel, onBackground=Color.White, onSurface=Color.White)) { Surface(Modifier.fillMaxSize(), color=Ink) { Column { if (detail != null) { Row(Modifier.fillMaxWidth().padding(20.dp), verticalAlignment=Alignment.CenterVertically) { Text("‹  Back", color=Lime, modifier=Modifier.clickable { detail=null }); Spacer(Modifier.width(18.dp)); Text(detail!!, fontSize=20.sp, fontWeight=FontWeight.Bold) }; InfoPage(detail!!) } else { Box(Modifier.weight(1f)) { when(current) { "Home" -> HomeScreen(onOpen={ current=it }, onDetail={detail=it}); "Movies" -> CatalogueScreen("Movies", "Movie catalogue", onDetail={detail=it}); "Series" -> CatalogueScreen("Series", "Series catalogue", onDetail={detail=it}); "Live TV" -> LiveScreen(onDetail={detail=it}); "Library" -> LibraryScreen(); else -> SettingsScreen(onDetail={detail=it}) } }; NavigationBar(containerColor=Panel) { listOf("Home","Movies","Series","Live TV","Library","Settings").forEach { item -> NavigationBarItem(selected=current==item, onClick={current=item}, icon={Text(when(item){"Home"->"⌂";"Movies"->"▣";"Series"->"▤";"Live TV"->"◉";"Library"->"♡";else->"⚙"},fontSize=18.sp)}, label={Text(item,fontSize=10.sp)}, colors=NavigationBarItemDefaults.colors(selectedIconColor=Lime, selectedTextColor=Lime, indicatorColor=Ink)) } } } } } } }

@Composable private fun Brand() { Row(verticalAlignment=Alignment.CenterVertically) { Box(Modifier.size(38.dp).background(Lime, RoundedCornerShape(12.dp)), contentAlignment=Alignment.Center) { Text("N", color=Ink, fontSize=25.sp, fontWeight=FontWeight.Black) }; Spacer(Modifier.width(10.dp)); Column { Text("NEXVIO", fontWeight=FontWeight.Black, letterSpacing=2.sp, fontSize=19.sp); Text("Movies • Series • Live TV", color=Muted, fontSize=11.sp) } } }
@Composable private fun HomeScreen(onOpen:(String)->Unit,onDetail:(String)->Unit) { LazyColumn(contentPadding=PaddingValues(20.dp), verticalArrangement=Arrangement.spacedBy(18.dp)) { item { Brand(); Spacer(Modifier.height(4.dp)); Row(Modifier.fillMaxWidth().background(Panel, RoundedCornerShape(14.dp)).clickable { onDetail("Search") }.padding(14.dp), verticalAlignment=Alignment.CenterVertically) { Text("⌕", color=Lime, fontSize=22.sp); Spacer(Modifier.width(10.dp)); Text("Search movies, series…", color=Muted) } }; item { Column(Modifier.fillMaxWidth().background(Panel, RoundedCornerShape(22.dp)).padding(20.dp)) { Text("YOUR NEXT STORY STARTS HERE", color=Lime, fontSize=10.sp, letterSpacing=1.5.sp, fontWeight=FontWeight.Bold); Spacer(Modifier.height(12.dp)); Text("Entertainment,\nyour way.", fontSize=32.sp, lineHeight=36.sp, fontWeight=FontWeight.ExtraBold); Spacer(Modifier.height(8.dp)); Text("Your personal hub for movies, series and live TV.", color=Muted); Spacer(Modifier.height(16.dp)); Text("SET UP YOUR LIBRARY  →", color=Ink, fontWeight=FontWeight.Bold, modifier=Modifier.background(Lime, RoundedCornerShape(12.dp)).clickable { onDetail("Content providers") }.padding(horizontal=14.dp, vertical=11.dp)) } }; item { Text("EXPLORE", color=Muted, fontSize=11.sp, letterSpacing=2.sp) }; item { Row(horizontalArrangement=Arrangement.spacedBy(10.dp)) { listOf("Movies","Series","Live TV").forEach { name -> Column(Modifier.weight(1f).background(Panel, RoundedCornerShape(16.dp)).clickable { onOpen(name) }.padding(12.dp)) { Text(when(name){"Movies"->"▣";"Series"->"▤";else->"◉"}, color=Lime, fontSize=22.sp); Spacer(Modifier.height(12.dp)); Text(name, fontWeight=FontWeight.Bold); Text("Explore", color=Muted, fontSize=11.sp) } } } }; item { EmptySection("Recently watched", "Your watch history will appear here once playback is available.") }; item { EmptySection("Favorites", "Save titles you love here when a catalogue is connected.") }; item { Text("Demo layout only • No streams or provider catalogue connected", color=Muted, fontSize=11.sp) } } }
@Composable private fun EmptySection(title:String, message:String) { Column(Modifier.fillMaxWidth().background(Panel, RoundedCornerShape(16.dp)).padding(16.dp)) { Text(title, fontSize=18.sp, fontWeight=FontWeight.Bold); Spacer(Modifier.height(8.dp)); Text(message, color=Muted, fontSize=13.sp); Spacer(Modifier.height(10.dp)); Text("NOT AVAILABLE YET", color=Lime, fontSize=10.sp, letterSpacing=1.sp) } }
@Composable private fun CatalogueScreen(title:String, subtitle:String,onDetail:(String)->Unit) { Column(Modifier.fillMaxSize().padding(20.dp)) { Text(title, fontSize=30.sp, fontWeight=FontWeight.ExtraBold); Text(subtitle, color=Muted); Spacer(Modifier.height(18.dp)); Row(Modifier.fillMaxWidth().background(Panel, RoundedCornerShape(14.dp)).clickable { onDetail("Search") }.padding(14.dp)) { Text("⌕  Search $title", color=Muted) }; Spacer(Modifier.height(20.dp)); EmptySection("Your $title collection", "Connect a compatible content provider in a later phase to browse real titles. No demonstration streams are provided.") } }
@Composable private fun LiveScreen(onDetail:(String)->Unit) { Column(Modifier.fillMaxSize().padding(20.dp)) { Text("Live TV", fontSize=30.sp, fontWeight=FontWeight.ExtraBold); Text("Your channels, all in one place", color=Muted); Spacer(Modifier.height(20.dp)); Button(onClick={onDetail("IPTV playlists")}, colors=ButtonDefaults.buttonColors(containerColor=Lime, contentColor=Ink), shape=RoundedCornerShape(14.dp), modifier=Modifier.fillMaxWidth()) { Text("＋  Set up playlist", fontWeight=FontWeight.Bold) }; Spacer(Modifier.height(18.dp)); EmptySection("No playlist configured", "Add an IPTV playlist in a future setup flow. No channels or playback streams are built in.") } }
@Composable private fun LibraryScreen() { LazyColumn(contentPadding=PaddingValues(20.dp), verticalArrangement=Arrangement.spacedBy(14.dp)) { item { Text("Your Library", fontSize=30.sp, fontWeight=FontWeight.ExtraBold); Text("A home for your saved and watched titles", color=Muted) }; item { EmptySection("Favorites", "Your saved titles will appear here when catalogue support is added.") }; item { EmptySection("Watch history", "Viewing history is not recorded in this phase.") }; item { EmptySection("Continue watching", "Playback progress will appear here once playback is implemented.") } } }
@Composable private fun SettingsScreen(onDetail:(String)->Unit) { LazyColumn(contentPadding=PaddingValues(20.dp), verticalArrangement=Arrangement.spacedBy(10.dp)) { item { Text("Settings", fontSize=30.sp, fontWeight=FontWeight.ExtraBold); Text("Make Nexvio yours", color=Muted); Spacer(Modifier.height(10.dp)) }; listOf("Appearance" to "Theme and visual preferences", "Playback preferences" to "Playback controls and defaults", "Content providers" to "Catalogue sources and addons", "IPTV playlists" to "Manage playlist sources", "Downloads" to "Offline media settings", "About Nexvio" to "Version and project information").forEach { (title,desc) -> item { Row(Modifier.fillMaxWidth().background(Panel, RoundedCornerShape(14.dp)).clickable { onDetail(title) }.padding(16.dp), verticalAlignment=Alignment.CenterVertically) { Column(Modifier.weight(1f)) { Text(title, fontWeight=FontWeight.SemiBold); Spacer(Modifier.height(4.dp)); Text(desc, color=Muted, fontSize=12.sp) }; Text("›", color=Lime, fontSize=24.sp) } } } } }
@Composable private fun InfoPage(title:String) { Column(Modifier.fillMaxWidth().padding(20.dp).background(Panel, RoundedCornerShape(18.dp)).padding(18.dp)) { Text(title, fontSize=23.sp, fontWeight=FontWeight.Bold); Spacer(Modifier.height(12.dp)); Text(when(title) { "About Nexvio" -> "Nexvio 1.0.0\nMovies • Series • Live TV\nAn original Android project foundation."; "Search" -> "Search will become available when a real catalogue provider is connected."; "Appearance" -> "The initial release uses Nexvio's dark appearance. Additional persisted appearance settings are planned."; "Playback preferences" -> "Playback is not implemented in Phase 1. No playback preferences are active yet."; "Content providers" -> "Provider and addon integration is planned for a later phase. No provider is currently connected."; "IPTV playlists" -> "Playlist import and channel playback are planned for a later phase. No playlist is configured."; "Downloads" -> "Downloads are not implemented in Phase 1. No storage permission is requested."; else -> "This feature is a foundation for a later Nexvio phase. It is not active in this release." }, color=Muted, lineHeight=23.sp); Spacer(Modifier.height(14.dp)); Text("PHASE 1 FOUNDATION", color=Lime, fontSize=10.sp, letterSpacing=1.5.sp) } }
